import React, { useState, useEffect } from 'react';
import {
    Box,
    TextField,
    Button,
    Typography,
    alpha,
    CircularProgress,
    Switch,
    FormControlLabel,
    IconButton,
    InputAdornment,
    Tooltip,
} from '@mui/material';
import {
    Person as PersonIcon,
    Email as EmailIcon,
    Lock as LockIcon,
    CardGiftcard as LifetimeIcon,
    VisibilityOff,
    Visibility,
    Autorenew as RefreshIcon,
} from '@mui/icons-material';
import BaseModal from '../BaseModal';
import { generatePassword } from '../../utils/passwordGenerator';

const INITIAL_FORM = {
    name: '',
    email: '',
    password: '',
    confirm_password: '',
    is_lifetime_free: false,
};

// Standard email shape. The local part intentionally excludes "+" so plus
// addressing (e.g. user+tag@gmail.com) is rejected.
const EMAIL_REGEX = /^[A-Za-z0-9._%-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)*\.[A-Za-z]{2,}$/;

const validateEmail = (rawEmail) => {
    const email = (rawEmail || '').trim();
    if (!email) return 'Email is required';
    if (email.includes('+')) return 'Email cannot contain a "+" sign';
    if (/\s/.test(email)) return 'Email cannot contain spaces';
    if (email.includes('..')) return 'Email cannot contain consecutive dots';
    const [local, ...domainParts] = email.split('@');
    if (domainParts.length !== 1) return 'Enter a valid email address';
    if (local.startsWith('.') || local.endsWith('.')) {
        return 'Enter a valid email address';
    }
    if (!EMAIL_REGEX.test(email)) return 'Enter a valid email address';
    return '';
};

const iconButtonSx = {
    width: 32,
    height: 32,
    p: 0.5,
    flexShrink: 0,
};

const refreshButtonSx = {
    ...iconButtonSx,
    color: '#4CC66E',
    bgcolor: 'rgba(76, 198, 110, 0.15)',
    '&:hover': {
        bgcolor: 'rgba(76, 198, 110, 0.28)',
    },
};

const AddUserModal = ({
    open,
    onClose,
    onSubmit,
    loading = false,
}) => {
    const [formData, setFormData] = useState(INITIAL_FORM);
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);
    const [errors, setErrors] = useState({});

    useEffect(() => {
        if (open) {
            setFormData(INITIAL_FORM);
            setErrors({});
            setShowPassword(false);
            setShowConfirmPassword(false);
        }
    }, [open]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        // Block the "+" sign and whitespace outright for email, and normalise case.
        const nextValue =
            name === 'email'
                ? value.replace(/[\s+]/g, '').toLowerCase()
                : value;
        setFormData((prev) => ({
            ...prev,
            [name]: nextValue,
        }));
        if (errors[name]) {
            setErrors((prev) => ({ ...prev, [name]: '' }));
        }
    };

    const handleLifetimeToggle = (e) => {
        setFormData((prev) => ({
            ...prev,
            is_lifetime_free: e.target.checked,
        }));
    };

    const handleRefreshPassword = () => {
        const password = generatePassword();
        setFormData((prev) => ({
            ...prev,
            password,
            confirm_password: password,
        }));
        setShowPassword(true);
        setShowConfirmPassword(true);
        setErrors((prev) => ({
            ...prev,
            password: '',
            confirm_password: '',
        }));
    };

    const validate = () => {
        const nextErrors = {};

        if (!formData.name.trim()) {
            nextErrors.name = 'Name is required';
        }
        const emailError = validateEmail(formData.email);
        if (emailError) {
            nextErrors.email = emailError;
        }
        if (!formData.password) {
            nextErrors.password = 'Password is required';
        } else if (formData.password.length < 6) {
            nextErrors.password = 'Password must be at least 6 characters';
        }
        if (!formData.confirm_password) {
            nextErrors.confirm_password = 'Please confirm the password';
        } else if (formData.password !== formData.confirm_password) {
            nextErrors.confirm_password = 'Passwords do not match';
        }

        setErrors(nextErrors);
        return Object.keys(nextErrors).length === 0;
    };

    const handleSubmit = (e) => {
        if (e) e.preventDefault();
        if (!validate()) return;

        onSubmit({
            name: formData.name.trim(),
            email: formData.email.trim(),
            password: formData.password,
            confirm_password: formData.confirm_password,
            is_lifetime_free: formData.is_lifetime_free,
        });
    };

    const isFormValid =
        formData.name.trim() &&
        !validateEmail(formData.email) &&
        formData.password &&
        formData.confirm_password &&
        formData.password === formData.confirm_password;

    const fieldLabelSx = {
        color: 'text.secondary',
        fontWeight: 700,
        mb: 1,
        display: 'flex',
        alignItems: 'center',
        gap: 1,
        textTransform: 'uppercase',
        letterSpacing: '0.05em',
    };

    const passwordFieldAdornment = (
        <InputAdornment position="end">
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5, mr: 0.5 }}>
                <Tooltip title="Generate random password">
                    <IconButton onClick={handleRefreshPassword} size="small" sx={refreshButtonSx}>
                        <RefreshIcon sx={{ fontSize: 16 }} />
                    </IconButton>
                </Tooltip>
                <IconButton
                    onClick={() => setShowPassword(!showPassword)}
                    size="small"
                    sx={{ ...iconButtonSx, color: 'text.secondary' }}
                >
                    {showPassword ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
                </IconButton>
            </Box>
        </InputAdornment>
    );

    const visibilityAdornment = (show, setShow) => (
        <InputAdornment position="end">
            <IconButton
                onClick={() => setShow(!show)}
                size="small"
                sx={{ ...iconButtonSx, color: 'text.secondary', mr: 0.5 }}
            >
                {show ? <VisibilityOff fontSize="small" /> : <Visibility fontSize="small" />}
            </IconButton>
        </InputAdornment>
    );

    const actions = (
        <Box sx={{ display: 'flex', gap: { xs: 1, sm: 2 }, width: '100%', flexDirection: { xs: 'column', sm: 'row' } }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{
                    color: 'text.secondary',
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)',
                    },
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleSubmit}
                disabled={loading || !isFormValid}
                sx={{
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    color: '#000',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(0, 0, 0, 0.5)',
                    },
                }}
            >
                {loading ? (
                    <CircularProgress size={24} color="inherit" />
                ) : (
                    'Add User'
                )}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title="Add New User"
            maxWidth="sm"
            actions={actions}
        >
            <Box
                component="form"
                onSubmit={handleSubmit}
                sx={{
                    pt: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 2.5,
                    width: '100%',
                }}
            >
                <Box>
                    <Typography variant="caption" sx={fieldLabelSx}>
                        <PersonIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Full Name
                    </Typography>
                    <TextField
                        fullWidth
                        name="name"
                        value={formData.name}
                        onChange={handleChange}
                        required
                        placeholder="Enter full name..."
                        variant="outlined"
                        autoComplete="off"
                        error={Boolean(errors.name)}
                        helperText={errors.name}
                    />
                </Box>

                <Box>
                    <Typography variant="caption" sx={fieldLabelSx}>
                        <EmailIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Email Address
                    </Typography>
                    <TextField
                        fullWidth
                        name="email"
                        type="email"
                        value={formData.email}
                        onChange={handleChange}
                        required
                        placeholder="Enter email address..."
                        variant="outlined"
                        autoComplete="off"
                        error={Boolean(errors.email)}
                        helperText={errors.email}
                    />
                </Box>

                <Box>
                    <Typography variant="caption" sx={fieldLabelSx}>
                        <LockIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Password
                    </Typography>
                    <TextField
                        fullWidth
                        name="password"
                        type={showPassword ? 'text' : 'password'}
                        value={formData.password}
                        onChange={handleChange}
                        required
                        placeholder="Enter password..."
                        variant="outlined"
                        autoComplete="new-password"
                        error={Boolean(errors.password)}
                        helperText={errors.password || 'Click refresh to generate an 8-character password'}
                        InputProps={{
                            endAdornment: passwordFieldAdornment,
                        }}
                    />
                </Box>

                <Box>
                    <Typography variant="caption" sx={fieldLabelSx}>
                        <LockIcon sx={{ fontSize: 16, color: '#4CC66E' }} />
                        Confirm Password
                    </Typography>
                    <TextField
                        fullWidth
                        name="confirm_password"
                        type={showConfirmPassword ? 'text' : 'password'}
                        value={formData.confirm_password}
                        onChange={handleChange}
                        required
                        placeholder="Confirm password..."
                        variant="outlined"
                        autoComplete="new-password"
                        error={Boolean(errors.confirm_password)}
                        helperText={errors.confirm_password}
                        InputProps={{
                            endAdornment: visibilityAdornment(showConfirmPassword, setShowConfirmPassword),
                        }}
                    />
                </Box>

                <Box
                    sx={{
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'space-between',
                        p: 2,
                        borderRadius: '12px',
                        border: '1px solid rgba(255, 255, 255, 0.08)',
                        bgcolor: 'rgba(255, 255, 255, 0.02)',
                    }}
                >
                    <Box>
                        <Typography
                            variant="caption"
                            sx={{
                                ...fieldLabelSx,
                                mb: 0.5,
                            }}
                        >
                            <LifetimeIcon sx={{ fontSize: 16, color: '#9F6EDA' }} />
                            Lifetime Free Access
                        </Typography>
                        <Typography variant="caption" sx={{ color: '#8B8D97' }}>
                            Grant this user free lifetime premium access
                        </Typography>
                    </Box>
                    <FormControlLabel
                        control={
                            <Switch
                                checked={formData.is_lifetime_free}
                                onChange={handleLifetimeToggle}
                                color="success"
                            />
                        }
                        label={formData.is_lifetime_free ? 'Yes' : 'No'}
                        sx={{
                            m: 0,
                            color: formData.is_lifetime_free ? '#4CC66E' : 'text.secondary',
                            '& .MuiTypography-root': {
                                fontWeight: 700,
                                fontSize: '0.75rem',
                            },
                        }}
                    />
                </Box>
            </Box>
        </BaseModal>
    );
};

export default AddUserModal;
