import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Box, Typography, Avatar, Tooltip, IconButton } from '@mui/material';
import DisplayChip from '../../../components/DisplayChip';
import FilterListIcon from '@mui/icons-material/FilterList';
import { Verified } from '@mui/icons-material';
import DataTable from '../../../components/DataTable';
import StatusDropdown from '../../../components/StatusDropdown';
import { useSelector } from 'react-redux';
import { toast } from 'react-hot-toast';
import { mapUserExport } from '../../../utils/exportMappers';
import { extractExportList, performExport } from '../../../utils/exportHelpers';
import ConfirmationModal from '../../../components/ConfirmationModal';
import UserNotificationModal from '../../../components/page_components/UserNotificationModal';
import EditUserModal from '../../../components/page_components/EditUserModal';
import AddUserModal from '../../../components/page_components/AddUserModal';
import ResetUserPasswordModal from '../../../components/page_components/ResetUserPasswordModal';
import dayjs from 'dayjs';
import AvatarView from '../../../components/AvatarView';

import { apiGetJson, BASE_URL } from '../../../utils/apiClient';
import { resetUserPassword } from '../../../utils/userApi';

const STATUS_OPTIONS = [
  { label: 'Unblock', value: 'unblocked', color: '#4CC66E' },
  { label: 'Block', value: 'blocked', color: '#FF5050' },
];





// ── Column Helpers ────────────────────────────────────────────────────────────

const BLOCK_CHIP = (blocked) => (
  <DisplayChip
    label={blocked ? 'Blocked' : 'Active'}
    size="small"
    sx={{
      bgcolor: blocked ? 'rgba(255,193,7,0.15)' : 'rgba(76,198,110,0.12)',
      color: blocked ? '#FFC107' : '#4CC66E',
      fontWeight: 600,
      fontSize: '0.72rem',
      fontFamily: "'Montserrat', sans-serif",
      borderRadius: '6px',
    }}
  />
);

const PLAN_CHIP = (plan) => {
  if (!plan) return <Typography sx={{  fontSize: '1rem' }}>Free</Typography>;
  const label = plan.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  return (
    <DisplayChip
      label={label}
      size="small"
      sx={{
        bgcolor: 'rgba(159,110,218,0.15)',
        color: '#9F6EDA',
        fontWeight: 600,
        fontSize: '0.72rem',
        fontFamily: "'Montserrat', sans-serif",
        borderRadius: '6px',
      }}
    />
  );
};

const resolveLastLoggedIn = (row) => {
  return (
    row.last_login || '-'
  );
};

const formatDateTime = (value) => {
  if (!value) return '-';
  return dayjs(value).isValid() ? dayjs(value).format('DD MMM YYYY, HH:mm') : '-';
};

// ── Component ─────────────────────────────────────────────────────────────────
const AllUsers = () => {
  const [users, setUsers]             = useState([]);
  const [isLoading, setIsLoading]     = useState(false);
  const [searchTerm, setSearchTerm]   = useState('');
  const [page, setPage]               = useState(0);           
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [totalCount, setTotalCount]   = useState(0);
  const [orderBy, setOrderBy]         = useState('created_at');
  const [order, setOrder]             = useState('desc');
  const [updatingStatus, setUpdatingStatus] = useState(null); 
  const [isExporting, setIsExporting] = useState(false);
  const [userToDelete, setUserToDelete] = useState(null);
  const [openDeleteModal, setOpenDeleteModal] = useState(false);
  const [userForNotification, setUserForNotification] = useState(null);
  const [openNotificationModal, setOpenNotificationModal] = useState(false);
  const [isSendingNotification, setIsSendingNotification] = useState(false);

  const [selectedUserForEdit, setSelectedUserForEdit] = useState(null);
  const [openEditModal, setOpenEditModal] = useState(false);
  const [isUpdatingUser, setIsUpdatingUser] = useState(false);
  const [openAddModal, setOpenAddModal] = useState(false);
  const [isCreatingUser, setIsCreatingUser] = useState(false);
  const [userForPasswordReset, setUserForPasswordReset] = useState(null);
  const [openResetPasswordModal, setOpenResetPasswordModal] = useState(false);
  const [isResettingPassword, setIsResettingPassword] = useState(false);

  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const statusFilter = searchParams.get('status');           // 'active' | null
  const subscriptionFilter = searchParams.get('subscription'); // 'subscribed' | null
  const token = useSelector((state) => state.auth.token);

  // ── Status Update ─────────────────────────────────────────────────────────
  const handleStatusUpdate = useCallback(async (userId, newStatus) => {
    setUpdatingStatus(userId);
    try {
      const apiStatus = newStatus === 'blocked' ? 'inactive' : 'active';
      const res = await fetch(`${BASE_URL}/users/${userId}/account-status`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ status: apiStatus }),
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || `Failed to update status to ${newStatus}`);
      }

      setUsers(prev => prev.map(u => 
        u.id === userId ? { ...u, block_status: newStatus === 'blocked' } : u
      ));
      toast.success(`User is now ${newStatus === 'blocked' ? 'Blocked' : 'Unblocked'}`);
    } catch (err) {
      console.error('Status update error:', err);
      toast.error(err.message || 'Something went wrong while updating status');
    } finally {
      setUpdatingStatus(null);
    }
  }, [token]);

  const handleDeleteUser = (user) => {
    setUserToDelete(user);
    setOpenDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!userToDelete || !token) return;
    const toastId = toast.loading('Deleting user...');
    try {
      const res = await fetch(`${BASE_URL}/users/${userToDelete.id}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to delete user');
      }

      toast.success('User deleted successfully', { id: toastId });
      fetchUsers(page + 1, rowsPerPage);
    } catch (err) {
      console.error('Delete error:', err);
      toast.error(err.message || 'Something went wrong while deleting user', { id: toastId });
    } finally {
      setOpenDeleteModal(false);
      setUserToDelete(null);
    }
  };

  const handleOpenNotification = (user) => {
    setUserForNotification(user);
    setOpenNotificationModal(true);
  };

  const handleEditClick = (user) => {
    setSelectedUserForEdit(user);
    setOpenEditModal(true);
  };

  const handleResetPasswordClick = (user) => {
    setUserForPasswordReset(user);
    setOpenResetPasswordModal(true);
  };

  const handleResetPasswordSubmit = async ({ newPassword }) => {
    if (!userForPasswordReset || !token) return;
    setIsResettingPassword(true);
    const toastId = toast.loading('Changing password...');
    try {
      await resetUserPassword(userForPasswordReset.id, newPassword, token);
      toast.success('User password changed successfully', { id: toastId });
      setOpenResetPasswordModal(false);
      setUserForPasswordReset(null);
    } catch (err) {
      console.error('Reset password error:', err);
      toast.error(err.message || 'Something went wrong while changing password', { id: toastId });
    } finally {
      setIsResettingPassword(false);
    }
  };

  const handleAddClick = () => {
    setOpenAddModal(true);
  };

  const handleAddSubmit = async (formData) => {
    if (!token) return;
    setIsCreatingUser(true);
    const toastId = toast.loading('Creating user...');
    try {
      const res = await fetch(`${BASE_URL}/users`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to create user');
      }

      toast.success('User created successfully', { id: toastId });
      setOpenAddModal(false);
      fetchUsers(page + 1, rowsPerPage);
    } catch (err) {
      console.error('Create user error:', err);
      toast.error(err.message || 'Something went wrong while creating user', { id: toastId });
    } finally {
      setIsCreatingUser(false);
    }
  };

  const handleEditSubmit = async (formData) => {
    if (!selectedUserForEdit || !token) return;
    setIsUpdatingUser(true);
    const toastId = toast.loading('Updating user details...');
    try {
      const res = await fetch(`${BASE_URL}/users/${selectedUserForEdit.id}/profile`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to update user details');
      }

      toast.success('User updated successfully', { id: toastId });
      setOpenEditModal(false);
      setSelectedUserForEdit(null);
      fetchUsers(page + 1, rowsPerPage);
    } catch (err) {
      console.error('Update error:', err);
      toast.error(err.message || 'Something went wrong while updating user', { id: toastId });
    } finally {
      setIsUpdatingUser(false);
    }
  };

  const handleSendNotification = async (formData) => {
    if (!userForNotification || !token) return;
    setIsSendingNotification(true);
    const toastId = toast.loading('Sending notification...');
    try {
      const payload = {
        title: formData.title,
        body: formData.message,
        type: 'custom',
        metadata: '',
        send_push: true,
        user_ids: [userForNotification.id],
      };

      const res = await fetch(`${BASE_URL}/notifications/broadcast-selected`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(payload),
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to send notification');
      }

      toast.success('Notification sent successfully', { id: toastId });
      setOpenNotificationModal(false);
      setUserForNotification(null);
    } catch (err) {
      console.error('Notification error:', err);
      toast.error(err.message || 'Something went wrong while sending notification', { id: toastId });
    } finally {
      setIsSendingNotification(false);
    }
  };

  // ── Columns ───────────────────────────────────────────────────────────────
  const COLUMNS = useMemo(() => [
    {
      id: 'name',
      label: 'Name',
      sortable: true,
      render: (row) => (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5 }}>
          <AvatarView
            src={row.profile?.profile_image}
            alt={row.name}
            previewTitle={row.name}
            sx={{
              width: 32,
              height: 32,
              fontSize: '0.75rem',
              fontWeight: 700,
            }}
          >
            {!row.profile?.profile_image && row.name?.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase()}
          </AvatarView>
          <Box>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.5 }}>
              <Typography sx={{ color: '#FFFFFF', fontSize: '0.8rem', fontFamily: "'Montserrat', sans-serif", fontWeight: 500, lineHeight: 1.2 }}>
                {row.name}
              </Typography>
              {row.is_verified && (
                <Tooltip title="Verified User">
                  <Verified sx={{ color: '#1D9BF0', fontSize: '1rem' }} />
                </Tooltip>
              )}
            </Box>
            <Typography sx={{ color: '#8B8D97', fontSize: '0.7rem', fontFamily: "'Montserrat', sans-serif" }}>
              {row.email}
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
      id: 'block_status',
      label: 'Status',
      sortable: true,
      render: (row) => (
        <StatusDropdown
          status={row.block_status ? 'blocked' : 'unblocked'}
          options={STATUS_OPTIONS}
          onStatusChange={(newStatus) => handleStatusUpdate(row.id, newStatus)}
          isLoading={updatingStatus === row.id}
        />
      ),
    },
    {
      id: 'plan',
      label: 'Plan',
      render: (row) => PLAN_CHIP(row.profile?.plan_key),
    },
    {
      id: 'created_at',
      label: 'Signed Up',
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: '#8B8D97', fontSize: '0.8rem', fontFamily: "'Montserrat', sans-serif" }}>
          {row.created_at
            ? dayjs(row.created_at).format('DD MMM YYYY')
            : '-'}
        </Typography>
      ),
    },
    {
      id: 'last_logged_in',
      label: 'Last Logged In',
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: '#8B8D97', fontSize: '0.8rem', fontFamily: "'Montserrat', sans-serif" }}>
          {formatDateTime(resolveLastLoggedIn(row))}
        </Typography>
      ),
    },
  ], [handleStatusUpdate, updatingStatus]);

  // ── Fetch ─────────────────────────────────────────────────────────────────
  const fetchUsers = useCallback(async (apiPage, limit) => {
    if (!token) return;
    setIsLoading(true);
    try {
      const params = {
        page: apiPage,
        limit: limit,
        sort_by: orderBy,
        sort_order: order,
      };

      if (searchTerm) {
        params.q = searchTerm;
      }
      if (statusFilter) {
        params.status = statusFilter;
      }
      if (subscriptionFilter) {
        params.subscription = subscriptionFilter;
      }

      const json = await apiGetJson('/users/with-profile', token, params);
      setUsers(json.data.users || []);
      setTotalCount(json.data.pagination?.total || 0);
    } catch (err) {
      console.error('Error fetching users:', err);
      toast.error(err.message || 'Something went wrong while fetching users');
    } finally {
      setIsLoading(false);
    }
  }, [token, orderBy, order, searchTerm, statusFilter, subscriptionFilter]);

  // Fetch on mount and whenever page/rowsPerPage/orderBy/order/searchTerm changes
  useEffect(() => {
    if (token) {
      fetchUsers(page + 1, rowsPerPage);
    }
  }, [page, rowsPerPage, fetchUsers, token]);

  const handleSortChange = useCallback((property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
    setPage(0);
  }, [orderBy, order]);

  const handleSearchChange = useCallback((val) => {
    setSearchTerm(val);
    setPage(0);
  }, []);

  const handleViewClick = useCallback((user) => {
    navigate(`/all-users/${user.id}`);
  }, [navigate]);

  const paginationConfig = useMemo(() => ({
    page,
    rowsPerPage,
    totalCount,
    onPageChange: (_, newPage) => setPage(newPage),
    onRowsPerPageChange: (e) => {
      setRowsPerPage(parseInt(e.target.value, 10));
      setPage(0);
    },
  }), [page, rowsPerPage, totalCount]);

  // ── CSV Export ────────────────────────────────────────────────────────────
  const handleExportUsers = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting users as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const params = {
        sort_by: orderBy,
        sort_order: order,
        not_pagination: 'true',
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      };

      if (searchTerm) {
        params.q = searchTerm;
      }

      const queryParams = new URLSearchParams(params);

      if (statusFilter) {
        queryParams.append('status', statusFilter);
      }
      if (subscriptionFilter) {
        queryParams.append('subscription', subscriptionFilter);
      }

      const res = await fetch(`${BASE_URL}/users/with-profile?${queryParams.toString()}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to fetch users for export');
      }

      // Robust extraction
      const items = extractExportList(json, 'users');
      const filename = `All_Users_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: (u) => mapUserExport(u, resolveLastLoggedIn, formatDateTime),
        format,
        filename,
        sheetName: 'Users',
        entityName: 'users',
        toastId,
      });
    } catch (err) {
      console.error('Export error:', err);
      toast.error(err.message || 'Something went wrong while exporting', { id: toastId });
    } finally {
      setIsExporting(false);
    }
  }, [token, searchTerm, orderBy, order, statusFilter, subscriptionFilter]);

  return (
    <Box sx={{ p: { xs: 1, md: 2 } }}>

     
      <DataTable
        title={
          subscriptionFilter === 'subscribed'
            ? 'Premium Users'
            : statusFilter
            ? `${statusFilter.charAt(0).toUpperCase() + statusFilter.slice(1)} Users`
            : 'All Users'
        }
        columns={COLUMNS}
        data={users}
        isLoading={isLoading}
        searchTerm={searchTerm}
        onSearchChange={handleSearchChange}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        onAddClick={handleAddClick}
        addLabel="Add User"
        onExport={handleExportUsers}
        isExporting={isExporting}
        pagination={paginationConfig}
        onViewClick={handleViewClick}
        onEditClick={handleEditClick}
        onDeleteClick={handleDeleteUser}
        onNotificationClick={handleOpenNotification}
        onResetPasswordClick={handleResetPasswordClick}
        emptyTitle="No users found"
        emptyMessage="No registered users were found in the system."
      />

      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete User?"
        message={`Are you sure you want to delete ${userToDelete?.name}? This action cannot be undone.`}
        confirmText="Delete"
        confirmColor="error"
      />

      <AddUserModal
        open={openAddModal}
        onClose={() => setOpenAddModal(false)}
        onSubmit={handleAddSubmit}
        loading={isCreatingUser}
      />

      <EditUserModal
        open={openEditModal}
        onClose={() => setOpenEditModal(false)}
        onSubmit={handleEditSubmit}
        userData={selectedUserForEdit}
        loading={isUpdatingUser}
      />

      <UserNotificationModal
        open={openNotificationModal}
        onClose={() => setOpenNotificationModal(false)}
        onSubmit={handleSendNotification}
        userData={userForNotification}
        loading={isSendingNotification}
      />

      <ResetUserPasswordModal
        open={openResetPasswordModal}
        onClose={() => {
          setOpenResetPasswordModal(false);
          setUserForPasswordReset(null);
        }}
        onSubmit={handleResetPasswordSubmit}
        userData={userForPasswordReset}
        loading={isResettingPassword}
      />
    </Box>
  );
};

export default AllUsers;


